SELECT stock_qty_bucket, min_cost, pct_books FROM (SELECT CASE WHEN stock_qty >= 366 THEN 'high' WHEN stock_qty >= 157 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, MIN(cost) AS min_cost, ROUND((100 * SUM(CASE WHEN category = 'Books' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_books FROM products WHERE stock_qty > 364 GROUP BY CASE WHEN stock_qty >= 366 THEN 'high' WHEN stock_qty >= 157 THEN 'mid' ELSE 'low' END) AS agg WHERE min_cost >= 530;
